<?php
declare(strict_types=1); require_once __DIR__.'/../config/config.php'; require_once __DIR__.'/../config/database.php'; require_once __DIR__.'/includes/auth.php';
$id=(int)($_GET['id']??$_POST['id']??0);$row=['title'=>'','slug'=>'','description'=>'','icon'=>'','is_active'=>1,'sort_order'=>0];$errors=[];if($id){$s=db()->prepare('SELECT * FROM services WHERE id=?');$s->execute([$id]);$row=$s->fetch()?:$row;}if($_SERVER['REQUEST_METHOD']==='POST'){foreach(['title','slug','description','icon','sort_order'] as $k)$row[$k]=trim((string)($_POST[$k]??''));$row['is_active']=isset($_POST['is_active'])?1:0;if($row['title']===''||$row['description']==='')$errors[]='Title and description are required.';if($row['slug']==='')$row['slug']=strtolower(trim(preg_replace('/[^a-z0-9]+/i','-', $row['title']),'-'));if(!$errors){if($id){db()->prepare('UPDATE services SET title=?,slug=?,description=?,icon=?,is_active=?,sort_order=? WHERE id=?')->execute([$row['title'],$row['slug'],$row['description'],$row['icon'],$row['is_active'],(int)$row['sort_order'],$id]);}else{db()->prepare('INSERT INTO services(title,slug,description,icon,is_active,sort_order) VALUES(?,?,?,?,?,?)')->execute([$row['title'],$row['slug'],$row['description'],$row['icon'],$row['is_active'],(int)$row['sort_order']]);}header('Location: services.php');exit;}}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= $id?'Edit':'Add' ?> Service</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-5" style="max-width:900px"><div class="d-flex justify-content-between mb-4"><h1><?= $id?'Edit':'Add' ?> Service</h1><a class="btn btn-outline-secondary" href="services.php">Back</a></div><?php foreach($errors as $e):?><div class="alert alert-danger"><?=htmlspecialchars($e)?></div><?php endforeach;?><form method="post" class="card border-0 shadow-sm p-4"><input type="hidden" name="id" value="<?=$id?>"><div class="row g-3"><div class="col-md-8"><label class="form-label">Title</label><input name="title" class="form-control" value="<?=htmlspecialchars($row['title'])?>" required></div><div class="col-md-4"><label class="form-label">Icon</label><input name="icon" class="form-control" value="<?=htmlspecialchars($row['icon'])?>" placeholder="bi-code-slash"></div><div class="col-12"><label class="form-label">Slug</label><input name="slug" class="form-control" value="<?=htmlspecialchars($row['slug'])?>"></div><div class="col-12"><label class="form-label">Description</label><textarea name="description" class="form-control" rows="5" required><?=htmlspecialchars($row['description'])?></textarea></div><div class="col-md-3"><label class="form-label">Sort order</label><input type="number" name="sort_order" class="form-control" value="<?=htmlspecialchars((string)$row['sort_order'])?>"></div><div class="col-12"><div class="form-check"><input class="form-check-input" type="checkbox" name="is_active" id="active" <?=((int)$row['is_active']?'checked':'')?>><label class="form-check-label" for="active">Active</label></div></div><div class="col-12"><button class="btn btn-primary">Save Service</button></div></div></form></main></body></html>